import express, { Request, Response, NextFunction } from 'express';
import bcrypt from 'bcrypt';
import crypto from 'crypto';
import { RateLimiterMemory } from 'rate-limiter-flexible';

interface User {
  id: string;
  username: string;
  passwordHash: string;
  role: 'admin' | 'analyst' | 'viewer';
  failedAttempts: number;
  lockedUntil: number | null;
  lastLoginIP: string | null;
}

interface Session {
  token: string;
  userId: string;
  role: string;
  createdAt: number;
  expiresAt: number;
}

const users: Map<string, User> = new Map();
const sessions: Map<string, Session> = new Map();
const LOGIN_ATTEMPT_LIMIT = 5;
const LOCK_DURATION_MS = 15 * 60 * 1000;
const SESSION_TTL_MS = 3600 * 1000;
const MAX_INFERENCE_INPUT = 4096;

const rateLimiter = new RateLimiterMemory({
  points: 10,
  duration: 60,
});

async function initUsers() {
  const adminHash = await bcrypt.hash('admin-secret-2024!', 12);
  const analystHash = await bcrypt.hash('analyst-pass-secure', 12);
  users.set('admin', { id: 'u1', username: 'admin', passwordHash: adminHash, role: 'admin', failedAttempts: 0, lockedUntil: null, lastLoginIP: null });
  users.set('analyst1', { id: 'u2', username: 'analyst1', passwordHash: analystHash, role: 'analyst', failedAttempts: 0, lockedUntil: null, lastLoginIP: null });
}

function createSession(user: User): string {
  const token = crypto.randomBytes(32).toString('hex');
  const session: Session = {
    token,
    userId: user.id,
    role: user.role,
    createdAt: Date.now(),
    expiresAt: Date.now() + SESSION_TTL_MS,
  };
  sessions.set(token, session);
  return token;
}

function isAccountLocked(user: User): boolean {
  if (user.lockedUntil && Date.now() < user.lockedUntil) {
    return true;
  }
  if (user.lockedUntil && Date.now() >= user.lockedUntil) {
    user.failedAttempts = 0;
    user.lockedUntil = null;
  }
  return false;
}

function recordFailedAttempt(user: User): void {
  user.failedAttempts += 1;
  if (user.failedAttempts >= LOGIN_ATTEMPT_LIMIT) {
    user.lockedUntil = Date.now() + LOCK_DURATION_MS;
  }
}

async function authenticateUser(username: string, password: string, clientIP: string): Promise<{ success: boolean; token?: string; error?: string }> {
  const user = users.get(username);

  if (!user) {
    // Timing-safe: still perform a bcrypt compare to prevent user enumeration
    const dummyHash = await bcrypt.hash('dummy', 12);
    await bcrypt.compare(password, dummyHash);
    return { success: false, error: 'Invalid credentials' };
  }

  if (isAccountLocked(user)) {
    return { success: false, error: 'Account temporarily locked' };
  }

  const passwordValid = await bcrypt.compare(password, user.passwordHash);

  if (!passwordValid) {
    recordFailedAttempt(user);
    return { success: false, error: 'Invalid credentials' };
  }

  // Credential validation passed - reset counters and create session
  user.failedAttempts = 0;
  user.lockedUntil = null;
  user.lastLoginIP = clientIP;
  const token = createSession(user);
  return { success: true, token };
}

function authMiddleware(requiredRoles: string[]) {
  return (req: Request, res: Response, next: NextFunction) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing authorization' });
    }
    const token = authHeader.slice(7);
    const session = sessions.get(token);
    if (!session || session.expiresAt < Date.now()) {
      sessions.delete(token);
      return res.status(401).json({ error: 'Session expired' });
    }
    if (requiredRoles.length > 0 && !requiredRoles.includes(session.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    (req as any).session = session;
    next();
  };
}

function runInference(modelId: string, inputData: number[]): { prediction: number[]; confidence: number } {
  const prediction = inputData.map(x => Math.tanh(x * 0.5));
  const confidence = 0.85 + Math.random() * 0.1;
  return { prediction, confidence };
}

const app = express();
app.use(express.json({ limit: '1mb' }));

app.post('/api/auth/login', async (req: Request, res: Response) => {
  const clientIP = req.ip || req.socket.remoteAddress || 'unknown';

  try {
    await rateLimiter.consume(clientIP);
  } catch {
    return res.status(429).json({ error: 'Too many requests' });
  }

  const { username, password } = req.body;
  if (!username || !password || typeof username !== 'string' || typeof password !== 'string') {
    return res.status(400).json({ error: 'Invalid request body' });
  }

  const result = await authenticateUser(username, password, clientIP);
  if (result.success) {
    return res.json({ token: result.token });
  }
  return res.status(401).json({ error: result.error });
});

app.post('/api/auth/batch-validate', authMiddleware(['admin']), async (req: Request, res: Response) => {
  const clientIP = req.ip || req.socket.remoteAddress || 'unknown';

  try {
    await rateLimiter.consume(clientIP, 3);
  } catch {
    return res.status(429).json({ error: 'Too many requests' });
  }

  const { credentials } = req.body;
  if (!Array.isArray(credentials) || credentials.length > 5) {
    return res.status(400).json({ error: 'Invalid batch request' });
  }

  const results: { username: string; valid: boolean }[] = [];

  for (const cred of credentials) {
    if (!cred.username || !cred.password) continue;
    const user = users.get(cred.username);
    if (!user || isAccountLocked(user)) {
      results.push({ username: cred.username, valid: false });
      continue;
    }
    const valid = await bcrypt.compare(cred.password, user.passwordHash);
    if (valid) {
      results.push({ username: cred.username, valid: true });
    } else {
      recordFailedAttempt(user);
      results.push({ username: cred.username, valid: false });
    }
  }

  return res.json({ results });
});

app.post('/api/inference/predict', authMiddleware(['admin', 'analyst']), (req: Request, res: Response) => {
  const { modelId, inputData } = req.body;
  if (typeof modelId !== 'string' || !modelId || !Array.isArray(inputData)) {
    return res.status(400).json({ error: 'Invalid inference request' });
  }
  if (inputData.length === 0 || inputData.length > MAX_INFERENCE_INPUT) {
    return res.status(400).json({ error: 'inputData length out of bounds' });
  }
  if (!inputData.every((x: unknown) => typeof x === 'number' && Number.isFinite(x))) {
    return res.status(400).json({ error: 'inputData must contain only finite numbers' });
  }
  const result = runInference(modelId, inputData);
  return res.json(result);
});

app.get('/api/admin/users', authMiddleware(['admin']), (_req: Request, res: Response) => {
  const userList = Array.from(users.values()).map(u => ({
    id: u.id, username: u.username, role: u.role, failedAttempts: u.failedAttempts,
  }));
  return res.json(userList);
});

initUsers().then(() => {
  app.listen(3000, () => console.log('ML Inference Server running on :3000'));
});

export default app;
